// Shared token logic: reading DTCG files, resolving references, and mapping tokens to and
// from Figma variables. Used by the build and check scripts in Node, and bundled into the
// GG Tokens Figma plugin. The plugin sandbox runs older JavaScript, so this file sticks to
// ES2017 syntax: no ?. or ??, no object spread, no Array.prototype.at, flat or flatMap.
// tools/build-figma-plugin.mjs checks that with a parser.

const TOKEN_FILES = ['color.json', 'color-roles.json', 'type.json', 'space.json', 'layout.json'];

// Which Figma variable collection each token file becomes. `root` is the first path segment,
// dropped from variable names inside that collection (color.green.300 -> Color / green/300).
const SYNC = [
  { file: 'color.json', collection: 'Color', root: 'color' },
  { file: 'color-roles.json', collection: 'Color roles', root: 'role' },
  { file: 'type.json', collection: 'Type', root: null },
  { file: 'space.json', collection: 'Space', root: 'space' },
  { file: 'layout.json', collection: 'Layout', root: null },
];

const FIGMA_TYPE = { color: 'COLOR', dimension: 'FLOAT', number: 'FLOAT', fontWeight: 'FLOAT', fontFamily: 'STRING' };

function isToken(node) {
  return !!node && typeof node === 'object' && !Array.isArray(node) && Object.prototype.hasOwnProperty.call(node, '$value');
}
function isRef(v) {
  return typeof v === 'string' && /^\{[^{}]+\}$/.test(v);
}
function refPath(v) {
  return v.slice(1, -1);
}
function clone(v) {
  return JSON.parse(JSON.stringify(v));
}

// Every token in a DTCG document, with its dotted path and inherited $type.
function flatten(doc) {
  const out = [];
  function walk(node, path, inheritedType) {
    const type = node.$type !== undefined ? node.$type : inheritedType;
    if (isToken(node)) {
      out.push({ path: path.join('.'), type: type, value: node.$value, description: node.$description, extensions: node.$extensions });
      return;
    }
    Object.keys(node).forEach(function (k) {
      const v = node[k];
      if (k.charAt(0) !== '$' && v && typeof v === 'object' && !Array.isArray(v)) walk(v, path.concat([k]), type);
    });
  }
  walk(doc, [], undefined);
  return out;
}

// Resolve {references} across all tokens. Throws on a missing reference or a cycle.
function resolveAll(tokens) {
  const byPath = new Map();
  tokens.forEach(function (t) { byPath.set(t.path, t); });
  const cache = new Map();
  function resolve(path, seen) {
    if (cache.has(path)) return cache.get(path);
    if (seen.indexOf(path) !== -1) throw new Error('reference cycle: ' + seen.concat([path]).join(' -> '));
    const t = byPath.get(path);
    if (!t) throw new Error('missing reference {' + path + '}' + (seen.length ? ' in ' + seen[seen.length - 1] : ''));
    const v = isRef(t.value) ? resolve(refPath(t.value), seen.concat([path])) : t.value;
    cache.set(path, v);
    return v;
  }
  const out = new Map();
  tokens.forEach(function (t) { out.set(t.path, resolve(t.path, [])); });
  return out;
}

// The $type that applies at a path, following group-level $type down the tree.
function typeAt(doc, keys) {
  let node = doc;
  let type = doc.$type;
  for (let i = 0; i < keys.length; i++) {
    node = node ? node[keys[i]] : undefined;
    if (node && node.$type !== undefined) type = node.$type;
  }
  return type;
}

// ---- color ------------------------------------------------------------------------------
function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const n = function (i) { return parseInt(h.slice(i, i + 2), 16) / 255; };
  return { r: n(0), g: n(2), b: n(4), a: h.length === 8 ? n(6) : 1 };
}
function rgbToHex(c) {
  const parts = [c.r, c.g, c.b];
  if (c.a !== undefined && c.a < 1) parts.push(c.a);
  return '#' + parts.map(function (x) { return ('0' + Math.round(x * 255).toString(16)).slice(-2); }).join('');
}

// ---- Figma mapping -----------------------------------------------------------------------
function varName(sync, path) {
  const parts = path.split('.');
  return (sync.root ? parts.slice(1) : parts).join('/');
}
function pathFromVar(sync, name) {
  const parts = name.split('/');
  return (sync.root ? [sync.root].concat(parts) : parts).join('.');
}

function scopesFor(t) {
  if (t.type === 'color') return ['ALL_FILLS', 'STROKE_COLOR', 'EFFECT_COLOR'];
  if (t.type === 'fontFamily') return ['FONT_FAMILY'];
  if (t.type === 'fontWeight') return ['FONT_WEIGHT'];
  if (/\.size$/.test(t.path)) return ['FONT_SIZE'];
  if (/\.line$/.test(t.path)) return ['LINE_HEIGHT'];
  if (/^space\./.test(t.path)) return ['GAP', 'WIDTH_HEIGHT'];
  if (t.type === 'dimension') return ['WIDTH_HEIGHT'];
  return [];
}

// A token value as a Figma value. References become { alias: path }; the plugin turns them into
// variable aliases.
function toFigmaValue(t) {
  if (isRef(t.value)) return { alias: refPath(t.value) };
  if (t.type === 'color') return hexToRgb(t.value);
  if (t.type === 'dimension') return typeof t.value === 'object' ? t.value.value : Number(t.value);
  if (t.type === 'fontFamily') return Array.isArray(t.value) ? t.value[0] : t.value;
  return t.value;
}

// Every token that becomes a Figma variable, as a plain spec.
function toFigmaSpecs(docs) {
  const specs = [];
  SYNC.forEach(function (sync) {
    const doc = docs[sync.file];
    if (!doc) return;
    flatten(doc).forEach(function (t) {
      const resolvedType = FIGMA_TYPE[t.type];
      if (!resolvedType) return;
      specs.push({
        collection: sync.collection, name: varName(sync, t.path), path: t.path, resolvedType: resolvedType,
        value: toFigmaValue(t), scopes: scopesFor(t), description: t.description || '',
      });
    });
  });
  return specs;
}

function fromFigmaValue(spec, previous, type) {
  const v = spec.value;
  if (v && typeof v === 'object' && v.alias) return '{' + v.alias + '}';
  if (spec.resolvedType === 'COLOR') return rgbToHex(v);
  if (spec.resolvedType === 'FLOAT') {
    const n = Math.round(v * 1000) / 1000;
    if (previous && typeof previous === 'object' && !Array.isArray(previous)) return { value: n, unit: previous.unit };
    if (type === 'dimension') return { value: n, unit: 'px' };
    return n;
  }
  if (spec.resolvedType === 'STRING' && Array.isArray(previous)) return [v].concat(previous.slice(1));
  return v;
}
function typeFromFigma(resolvedType, path) {
  if (resolvedType === 'COLOR') return 'color';
  if (resolvedType === 'STRING') return /family/.test(path) ? 'fontFamily' : 'string';
  return /\.(size|line)$/.test(path) || /^space\./.test(path) ? 'dimension' : 'number';
}

// Write Figma variable values back into the repo's token documents. Only $value changes:
// structure, descriptions and extensions stay as the repo has them. New variables become new
// tokens. Tokens with no matching variable are left alone and listed as `missing`.
function mergeSpecs(docs, specs) {
  const next = clone(docs);
  const changes = [];
  const added = [];
  const seen = {};
  specs.forEach(function (s) {
    let sync = null;
    SYNC.forEach(function (x) { if (x.collection === s.collection) sync = x; });
    if (!sync || !next[sync.file]) return;
    const path = pathFromVar(sync, s.name);
    seen[path] = true;
    const keys = path.split('.');
    let node = next[sync.file];
    for (let i = 0; i < keys.length - 1; i++) {
      if (!node[keys[i]] || typeof node[keys[i]] !== 'object') node[keys[i]] = {};
      node = node[keys[i]];
    }
    const leaf = keys[keys.length - 1];
    const existing = node[leaf];
    const value = fromFigmaValue(s, existing ? existing.$value : undefined, typeAt(next[sync.file], keys));
    if (!isToken(existing)) {
      node[leaf] = { $type: typeFromFigma(s.resolvedType, path), $value: value };
      added.push(path);
    } else if (JSON.stringify(existing.$value) !== JSON.stringify(value)) {
      changes.push({ path: path, from: existing.$value, to: value });
      existing.$value = value;
    }
  });
  const missing = [];
  SYNC.forEach(function (sync) {
    if (!next[sync.file]) return;
    flatten(next[sync.file]).forEach(function (t) { if (FIGMA_TYPE[t.type] && !seen[t.path]) missing.push(t.path); });
  });
  return { docs: next, changes: changes, added: added, missing: missing };
}

// Text styles the plugin builds from the type tokens: one per role per set.
const TEXT_ROLES = ['display', 'h1', 'lead', 'h2', 'h3', 'h4', 'body', 'small', 'caption'];
const TEXT_ROLE_LABEL = { display: 'Display', h1: 'Heading 1', lead: 'Lead', h2: 'Heading 2', h3: 'Heading 3', h4: 'Heading 4', body: 'Body', small: 'Small', caption: 'Caption' };
const TEXT_SETS = { wide: 'Wide', narrow: 'Narrow' };
function figmaFontStyle(weight, italic) {
  if (italic) return weight >= 700 ? 'Bold Italic' : 'Italic';
  if (weight >= 800) return 'ExtraBold';
  if (weight >= 700) return 'Bold';
  if (weight >= 500) return 'Medium';
  return 'Regular';
}

// Send changes: a plain next step for the GitHub errors people are likely to hit.
// info is { status, path, message } from the failed request. Returns '' when there is nothing to add.
function githubHint(info, repo, base) {
  const status = info && info.status;
  const path = (info && info.path) || '';
  const message = (info && info.message) || '';
  const name = repo.split('/')[1] || repo;
  if (status === 401) {
    return 'GitHub did not accept the access token. It may be mistyped, expired or deleted. Make a new one and paste it into Access token.';
  }
  if (status === 403 && /not accessible by/i.test(message)) {
    return 'The token can read ' + repo + ' but can’t change it. On GitHub, go to Settings, Developer settings, Fine-grained tokens, and edit this token. ' +
      'Under Repository access, choose Only select repositories and pick ' + name + '. ' +
      'Under Repository permissions, set Contents and Pull requests to Read and write. Then send again.';
  }
  if (status === 403 && /rate limit/i.test(message)) {
    return 'GitHub’s request limit was reached. Wait a few minutes, then send again.';
  }
  if (status === 404 && path.indexOf('/git/ref/heads/') !== -1) {
    return 'Couldn’t find the branch ' + base + ' in ' + repo + '. Check Base branch and the repository name. If the repository is private, the token also needs access to it.';
  }
  if (status === 404 && path.indexOf('/contents/tokens/') !== -1) {
    return 'The token files aren’t on ' + base + '. Set Base branch to a branch that has tokens/*.json.';
  }
  if (status === 404) {
    return 'Couldn’t find ' + repo + ', or the token can’t see it. Check the repository name and the token’s repository access.';
  }
  if (status === 422 && /reference already exists/i.test(message)) {
    return 'A branch with this name already exists. Wait a minute, then send again.';
  }
  return '';
}

// GG Tokens, main thread. tools/build-figma-plugin.mjs bundles this file after TOKENS (the
// repo's token files) and tools/lib/tokens.mjs. ES2017 only: the Figma sandbox is older JS.

figma.showUI(__html__, { width: 440, height: 600, themeColors: true });

const MODE_NAME = 'Value';
const SETTINGS_KEY = 'gg-tokens-settings';

function post(type, data) {
  figma.ui.postMessage(Object.assign({ type: type }, data || {}));
}

async function collectionsByName() {
  const list = await figma.variables.getLocalVariableCollectionsAsync();
  const map = {};
  list.forEach(function (c) { map[c.name] = c; });
  return map;
}

function ensureCollection(name, byName) {
  let c = byName[name];
  if (!c) {
    c = figma.variables.createVariableCollection(name);
    byName[name] = c;
  }
  // Starter files allow one mode per collection; name it for what it holds.
  if (c.modes.length && c.modes[0].name !== MODE_NAME) c.renameMode(c.modes[0].modeId, MODE_NAME);
  return c;
}

function numberAt(resolved, path) {
  const v = resolved.get(path);
  return typeof v === 'object' ? v.value : Number(v);
}

// ---- load tokens into this file ---------------------------------------------------------
async function importTokens() {
  const specs = toFigmaSpecs(TOKENS);
  const byName = await collectionsByName();
  const existing = await figma.variables.getLocalVariablesAsync();
  const byKey = {};
  existing.forEach(function (v) { byKey[v.variableCollectionId + '|' + v.name] = v; });

  const byPath = {};
  let created = 0;
  let changed = 0;

  // First pass: make sure every variable exists, so aliases can point at any of them.
  for (const s of specs) {
    const c = ensureCollection(s.collection, byName);
    const key = c.id + '|' + s.name;
    let v = byKey[key];
    if (v && v.resolvedType !== s.resolvedType) {
      v.remove();
      v = null;
    }
    if (!v) {
      v = figma.variables.createVariable(s.name, c, s.resolvedType);
      byKey[key] = v;
      created++;
    }
    v.description = s.description;
    v.scopes = s.scopes;
    byPath[s.path] = { variable: v, collection: c };
  }

  // Second pass: set values.
  for (const s of specs) {
    const entry = byPath[s.path];
    const modeId = entry.collection.defaultModeId;
    let value = s.value;
    if (value && typeof value === 'object' && value.alias) {
      const target = byPath[value.alias];
      if (!target) throw new Error('No variable for {' + value.alias + '}');
      value = figma.variables.createVariableAlias(target.variable);
    }
    const before = JSON.stringify(entry.variable.valuesByMode[modeId]);
    entry.variable.setValueForMode(modeId, value);
    if (before !== JSON.stringify(entry.variable.valuesByMode[modeId])) changed++;
  }

  const styles = await buildTextStyles(byPath);
  return { total: specs.length, created: created, changed: changed, styles: styles.count, unbound: styles.unbound };
}

// One text style per type role per set, bound to the size and line height variables.
async function buildTextStyles(byPath) {
  const all = [];
  Object.keys(TOKENS).forEach(function (f) { flatten(TOKENS[f]).forEach(function (t) { all.push(t); }); });
  const resolved = resolveAll(all);
  const familyValue = resolved.get('font.family.sans');
  const family = Array.isArray(familyValue) ? familyValue[0] : familyValue;
  const typeDoc = TOKENS['type.json'].type;

  const existing = await figma.getLocalTextStylesAsync();
  const byName = {};
  existing.forEach(function (s) { byName[s.name] = s; });

  let count = 0;
  let unbound = 0;
  for (const setKey of Object.keys(TEXT_SETS)) {
    for (const role of TEXT_ROLES) {
      const ext = typeDoc[role].$extensions || {};
      const italic = ext['com.growgood.fontStyle'] === 'italic';
      const weight = numberAt(resolved, 'type.' + role + '.weight');
      const fontName = { family: family, style: figmaFontStyle(weight, italic) };
      await figma.loadFontAsync(fontName);

      const name = TEXT_SETS[setKey] + '/' + TEXT_ROLE_LABEL[role];
      let style = byName[name];
      if (!style) {
        style = figma.createTextStyle();
        style.name = name;
      }
      style.fontName = fontName;
      style.fontSize = numberAt(resolved, 'type.' + role + '.' + setKey + '.size');
      style.lineHeight = { unit: 'PIXELS', value: numberAt(resolved, 'type.' + role + '.' + setKey + '.line') };
      style.description = 'TYPE-002 (' + (setKey === 'wide' ? '768px and up, D-026' : 'under 768px, D-027') + ')';

      ['size', 'line'].forEach(function (part) {
        const entry = byPath['type.' + role + '.' + setKey + '.' + part];
        const field = part === 'size' ? 'fontSize' : 'lineHeight';
        try {
          style.setBoundVariable(field, entry.variable);
        } catch (e) {
          unbound++; // older Figma builds cannot bind text style fields; the values are set either way
        }
      });
      count++;
    }
  }
  return { count: count, unbound: unbound };
}

// ---- read variables back for export -------------------------------------------------------
async function collectSpecs() {
  const byName = await collectionsByName();
  const vars = await figma.variables.getLocalVariablesAsync();
  const syncById = {};
  SYNC.forEach(function (sync) {
    const c = byName[sync.collection];
    if (c) syncById[c.id] = { sync: sync, collection: c };
  });
  const pathById = {};
  vars.forEach(function (v) {
    const hit = syncById[v.variableCollectionId];
    if (hit) pathById[v.id] = pathFromVar(hit.sync, v.name);
  });
  const specs = [];
  const skipped = [];
  vars.forEach(function (v) {
    const hit = syncById[v.variableCollectionId];
    if (!hit) return;
    let value = v.valuesByMode[hit.collection.defaultModeId];
    if (value && value.type === 'VARIABLE_ALIAS') {
      if (!pathById[value.id]) {
        skipped.push(hit.sync.collection + ' / ' + v.name + ' points outside the token collections');
        return;
      }
      value = { alias: pathById[value.id] };
    }
    specs.push({ collection: hit.sync.collection, name: v.name, resolvedType: v.resolvedType, value: value });
  });
  return { specs: specs, skipped: skipped };
}

async function status() {
  const byName = await collectionsByName();
  const vars = await figma.variables.getLocalVariablesAsync();
  const ids = {};
  SYNC.forEach(function (sync) { if (byName[sync.collection]) ids[byName[sync.collection].id] = true; });
  return { inFile: vars.filter(function (v) { return ids[v.variableCollectionId]; }).length, inRepo: toFigmaSpecs(TOKENS).length };
}

// ---- messages from the panel --------------------------------------------------------------
figma.ui.onmessage = async function (msg) {
  try {
    if (msg.type === 'ready') {
      const settings = (await figma.clientStorage.getAsync(SETTINGS_KEY)) || {};
      post('init', { settings: settings, status: await status() });
    } else if (msg.type === 'import') {
      const result = await importTokens();
      post('imported', { result: result, status: await status() });
      figma.notify('Tokens loaded: ' + result.total + ' variables, ' + result.styles + ' text styles');
    } else if (msg.type === 'collect') {
      const collected = await collectSpecs();
      post('collected', collected);
    } else if (msg.type === 'save-settings') {
      await figma.clientStorage.setAsync(SETTINGS_KEY, msg.settings);
      post('saved', {});
    } else if (msg.type === 'open' && /^https:\/\/github\.com\//.test(msg.url)) {
      figma.openExternal(msg.url);
    } else if (msg.type === 'close') {
      figma.closePlugin();
    }
  } catch (e) {
    post('error', { message: String(e && e.message ? e.message : e) });
  }
};
